const paths={book:'M3 4q5-2 9 1 4-3 9-1v16q-5-2-9 1-4-3-9-1z M12 5v16',mic:'M9 4a3 3 0 0 1 6 0v8a3 3 0 0 1-6 0z M5 10v2a7 7 0 0 0 14 0v-2 M12 19v3 M8 22h8',speaker:'M3 9h4l5-4v14l-5-4H3z M16 8q4 4 0 8 M19 5q7 7 0 14',check:'M5 12l4 4L19 6',science:'M9 3h6 M10 3v7L4 20h16l-6-10V3 M8 14h8',math:'M5 3h14v18H5z M8 7h8 M8 12h2 M14 12h2 M8 16h2 M14 16h2',english:'M3 19L8 5l5 14 M5 14h6 M16 11q5-3 5 2v6 M21 14q-6-2-6 2t6 1',leaf:'M12 21v-9 M12 13Q0 13 3 4q10-2 9 9 M12 16q0-13 9-12 3 11-9 12',history:'M3 11a9 9 0 1 1 2 7 M3 4v7h7 M12 6v6l4 2',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0 M15 15l6 6',down:'M12 3v13 M7 11l5 5 5-5 M4 19v3h16v-3',close:'M6 6l12 12 M18 6L6 18',end:'M3 12q9-9 18 0v5h-5v-5q-4-2-8 0v5H3z',captions:'M3 4h18v14H9l-5 4v-4H3z M7 9h10 M7 13h7',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 22v-3q0-7 8-7t8 7v3',send:'M3 3l19 9-19 9 4-9z M7 12h15',pause:'M8 5v14 M16 5v14',arrow:'M5 12h14 M14 7l5 5-5 5'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.book}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const advisors=[{name:'Ms Lam'},{name:'Mr Chan'},{name:'Ms May'}];
const healthOptions=['Better than usual','Same as usual','Less than usual','Much less than usual'];
const surveyIntro="Let's go through a survey of your general health. It only takes 3 minutes and we can continue our conversation as soon as you complete this survey.";
let selected=0,session=false,phase='intro',turns=0,answered=null,transcript=[],last='',caption=true,ended=false,started=0,tick=null,speech=null,recognition=null,voiceToken=0,listening=false,speaking=false,historyOpen=true;
const $=s=>document.querySelector(s),app=$('#app'),advisor=()=>advisors[selected];
function avatar(i,small=false){return `<span class="avatar a${i} ${small?'tiny':''}" aria-hidden="true"></span>`}
function brand(){return `<div class="brand">${icon('book')}<span>City University of Hong Kong</span></div>`}
function selectPage(){stopAudio();clearInterval(tick);session=false;app.className='';app.innerHTML=`<header>${brand()}<nav class="steps" aria-label="Learning steps"><span class="active"><b>1</b>Choose an advisor</span><i></i><span><b>2</b>Start talking</span></nav></header><main class="choose"><div class="intro"><h1>Welcome to Academic Advisory Portal</h1><p>Choose your academic advisor to begin your session.</p></div><div class="cards">${advisors.map((a,i)=>`<button class="advisor ${selected===i?'selected':''}" aria-pressed="${selected===i}" data-select="${i}">${selected===i?`<span class="selection">${icon('check')}</span>`:''}<div class="avatar a${i}" aria-hidden="true"></div><h2>${a.name}</h2></button>`).join('')}</div><div class="start"><button class="primary" id="start">${icon('mic')}Start Session</button><p class="fine">Speak at your own pace. You can also type your answers.</p></div><p class="demo">Interactive preview · Browser voice</p></main>`;document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selected=+b.dataset.select;selectPage();$(`[data-select="${selected}"]`).focus()});$('#start').onclick=startSession;document.title='Academic Advisory Portal · City University of Hong Kong'}
function startSession(){stopAudio();session=true;ended=false;phase='survey';turns=0;answered=null;transcript=[];caption=true;historyOpen=true;started=Date.now();app.className='session';const a=advisor();app.innerHTML=`<header>${brand()}<div class="header-advisor">${avatar(selected,true)}<span>${a.name}</span></div><div class="topic">Academic Advisory Portal</div><button id="end" class="danger">${icon('end')}End conversation</button></header><main class="workspace"><section class="main-column" aria-label="Conversation with ${a.name}"><div class="advisor-label"><span>Academic Advisor</span><strong>${a.name}</strong></div><div class="stage ${selected===2?'other may':selected===1?'other':''}"><div class="scene" role="img" aria-label="${a.name} in a calm classroom"></div>${selected?`<div class="hero-avatar avatar a${selected}" aria-hidden="true"></div>`:''}<div class="presence"><span class="dot"></span><span id="presence-text">${a.name} · Ready</span></div><div class="timer">${icon('clock')}<span id="time">00:00</span></div><div class="subtitle" id="subtitle"><strong>${a.name}</strong><span id="caption-text"></span></div><section class="quiz" id="quiz" aria-label="Multiple-choice question" hidden></section><div class="summary" id="summary" hidden></div></div><div class="controls"><button class="primary" id="mic">${icon('mic')}Start speaking</button><button class="secondary" id="replay">${icon('speaker')}Replay</button><button class="secondary" id="captions" aria-pressed="true">${icon('captions')}Captions</button><button class="secondary history-toggle" id="show-history" aria-expanded="true">${icon('history')}History</button></div><p class="status" id="status" role="status">You can speak or type your answer.</p><form class="text-form" id="reply"><input id="answer-text" aria-label="Your answer" placeholder="Or type your answer…" maxlength="600" autocomplete="off"><button class="secondary" aria-label="Send answer">${icon('send')}Send</button></form><p class="demo">Guided session preview · No live AI connection</p></section><aside class="history" aria-label="Conversation history"><div class="history-top"><h2>${icon('history')}Chat history</h2><button id="hide-history" class="icon-button" aria-label="Hide conversation history">${icon('close')}</button></div><label class="search">${icon('search')}<input id="search" type="search" placeholder="Search conversation" aria-label="Search conversation"></label><div class="messages" id="messages" role="log" aria-label="Conversation messages"></div><button class="secondary latest" id="latest">${icon('down')}Back to latest</button><p class="history-note">Available during this session only</p></aside><aside class="survey" aria-label="General health survey"><div class="survey-heading">General health survey <span>3 minutes</span></div><p class="survey-intro">Let's go through a survey of your general health. It only takes 3 minutes and we can continue our conversation as soon as you complete this survey.</p><div class="survey-progress"><span>Question</span><strong>3/12</strong></div><div class="progress-track" aria-hidden="true"><i></i></div><fieldset id="health-options"><legend>Have you recently been able to concentrate on whatever you're doing?</legend>${healthOptions.map((option,i)=>`<label class="health-option"><input type="radio" name="concentration" value="${i}"><span>${option}</span></label>`).join('')}</fieldset><p id="survey-status" role="status">Choose the response that best describes your experience.</p><button class="primary" id="confirm-survey" disabled>Confirm response ${icon('arrow')}</button><p class="survey-note">Preview of question 3. Remaining questions are not yet available. Your response stays in this session.</p></aside></main><dialog id="end-dialog"><h2>Finish for now?</h2><p>You can still read your conversation history after ending this session.</p><div class="dialog-actions"><button class="secondary" id="cancel-end">Keep talking</button><button class="danger" id="confirm-end">End conversation</button></div></dialog>`;
$('#end').onclick=()=>$('#end-dialog').showModal();$('#cancel-end').onclick=()=>$('#end-dialog').close();$('#confirm-end').onclick=()=>{$('#end-dialog').close();finish()};$('#mic').onclick=listen;$('#replay').onclick=()=>speak(last);$('#captions').onclick=()=>{caption=!caption;$('#captions').setAttribute('aria-pressed',String(caption));$('#subtitle').hidden=!caption||phase==='quiz'||ended};$('#reply').onsubmit=e=>{e.preventDefault();submit($('#answer-text').value)};$('#search').oninput=()=>renderHistory(false);$('#latest').onclick=()=>{$('#search').value='';renderHistory(true)};$('#hide-history').onclick=()=>toggleHistory(false);$('#show-history').onclick=()=>{toggleHistory(!historyOpen);if(historyOpen)document.querySelector('.history').scrollIntoView({block:'nearest'})};clearInterval(tick);tick=setInterval(()=>{if(!session||ended)return;const seconds=Math.floor((Date.now()-started)/1000);$('#time').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')},1000);document.querySelectorAll('[name=concentration]').forEach(r=>r.onchange=()=>{$('#confirm-survey').disabled=false;document.querySelectorAll('.health-option').forEach(l=>l.classList.toggle('selected',l.querySelector('input').checked))});$('#confirm-survey').onclick=confirmSurvey;say(surveyIntro);document.title='Academic Advisory Session · City University of Hong Kong'}
function toggleHistory(open){historyOpen=open;app.classList.toggle('history-hidden',!open);$('#show-history').setAttribute('aria-expanded',String(open))}
function message(who,text){transcript.push({who,text,time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})});renderHistory(true)}
function renderHistory(scroll){const query=$('#search').value.toLowerCase().trim();const filtered=transcript.map((m,i)=>({...m,i})).filter(m=>m.text.toLowerCase().includes(query)||(m.who==='user'?'you':advisor().name.toLowerCase()).includes(query));$('#messages').innerHTML=filtered.length?filtered.map(m=>`<article class="message ${m.who==='user'?'user':''}">${m.who==='user'?`<span class="user-icon">${icon('user')}</span>`:avatar(selected,true)}<div class="message-body"><div class="message-meta"><strong>${m.who==='user'?'You':advisor().name}</strong><time>${m.time}</time></div><div class="voice-message"><button class="audio-play" data-replay="${m.i}" aria-label="Read message ${m.i+1} aloud">${icon('speaker')}</button><div class="sound-wave" aria-hidden="true">${Array.from({length:19},(_,i)=>`<i style="height:${[9,17,26,14,31,22,12][i%7]}px"></i>`).join('')}</div></div><button class="text-toggle" data-text="${m.i}" aria-expanded="${!!query}" aria-controls="message-text-${m.i}">${query?'Hide text':'Show text'}</button><p class="transcript-text" id="message-text-${m.i}" ${query?'':'hidden'}>${esc(m.text)}</p></div></article>`).join(''):'<p class="no-results">No matching messages. Try a different word.</p>';document.querySelectorAll('[data-replay]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.voice-message').forEach(n=>n.classList.remove('playing'));b.closest('.voice-message').classList.add('playing');speak(transcript[+b.dataset.replay].text)});document.querySelectorAll('[data-text]').forEach(b=>b.onclick=()=>{const p=$('#message-text-'+b.dataset.text);p.hidden=!p.hidden;b.textContent=p.hidden?'Show text':'Hide text';b.setAttribute('aria-expanded',String(!p.hidden))});if(scroll&&!query)$('#messages').scrollTop=$('#messages').scrollHeight}
function status(text){if($('#status'))$('#status').textContent=text}
function voiceUI(){if(!session)return;$('#presence-text').textContent=advisor().name+' · '+(ended?'Session ended':listening?'Listening':speaking?'Speaking':'Your turn');document.querySelector('.stage').classList.toggle('talking',speaking);if(!speaking)document.querySelectorAll('.voice-message').forEach(n=>n.classList.remove('playing'));$('#mic').innerHTML=icon(listening?'pause':'mic')+(listening?'Stop listening':'Start speaking')}
function stopAudio(){voiceToken++;window.speechSynthesis?.cancel();if(recognition){recognition.onend=null;recognition.onerror=null;recognition.onresult=null;recognition.abort();recognition=null}listening=false;speaking=false;if(session)voiceUI()}
function say(text){last=text;message('advisor',text);$('#caption-text').textContent=text;speak(text)}
function speak(text){if(!text)return;stopAudio();if(!('speechSynthesis'in window)){status('Voice playback is not available here. You can read the captions and history.');return}const token=voiceToken;speech=new SpeechSynthesisUtterance(text);speech.lang='en-GB';speech.rate=.9;const voices=speechSynthesis.getVoices();const voice=voices.find(v=>v.lang==='en-GB')||voices.find(v=>v.lang.startsWith('en'));if(voice)speech.voice=voice;speech.onstart=()=>{if(token!==voiceToken)return;speaking=true;voiceUI();status('Your advisor is speaking. You can interrupt to answer.')};speech.onend=()=>{if(token!==voiceToken)return;speaking=false;voiceUI();status(ended?'Session ended. Your history is still available.':'Your turn. Speak or type your answer.')};speech.onerror=()=>{if(token!==voiceToken)return;speaking=false;voiceUI();status('Audio could not play. Try Replay, or read the captions.')};speechSynthesis.speak(speech)}
function confirmSurvey(){const choice=document.querySelector('[name=concentration]:checked');if(!choice||ended)return;const text=healthOptions[+choice.value];message('user','Question 3: '+text);$('#health-options').disabled=true;$('#confirm-survey').disabled=true;$('#confirm-survey').textContent='Response noted';$('#survey-status').textContent='Your response is noted for this session. The remaining survey questions have not been added to this preview.';phase='conversation';say('Thank you for sharing. This preview contains question 3 only. What would you like to discuss about your studies?')}
function submit(raw){const text=raw.trim();if(!text||ended)return;$('#answer-text').value='';stopAudio();if(phase==='survey'){const i=healthOptions.findIndex(o=>o.toLowerCase()===text.toLowerCase().replace(/[.!?]$/,''));if(i>=0){const radio=document.querySelector(`[name=concentration][value="${i}"]`);radio.checked=true;radio.onchange();status('Your response is selected. Choose Confirm response to submit it.');return}}message('user',text);if(phase==='survey'){say('Please choose the response that best describes your experience in the survey panel. You can confirm it when you are ready.')}else{say('Thank you for sharing. Your message is in the chat history. This is a guided preview; a live academic advisor connection has not been added yet.')}}

function listen(){if(ended)return;if(listening){recognition?.stop();return}const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R){status('Speech recognition is not supported in this browser. Please type your answer below.');$('#answer-text').focus();return}stopAudio();const token=voiceToken;const r=new R();recognition=r;r.lang='en-GB';r.interimResults=false;r.continuous=false;r.onstart=()=>{if(token!==voiceToken)return;listening=true;voiceUI();status('Listening… Speak in English, then pause.')};r.onresult=e=>{if(token!==voiceToken)return;submit(e.results[0][0].transcript)};r.onerror=e=>{if(token!==voiceToken)return;status(e.error==='not-allowed'?'Microphone access was not allowed. Enable it in your browser or type below.':e.error==='no-speech'?'No speech detected. Please try again or type below.':'Speech recognition is unavailable. Please type your answer below.')};r.onend=()=>{if(token!==voiceToken)return;listening=false;recognition=null;voiceUI();if($('#status').textContent.startsWith('Listening'))status('No answer received. Try again or type below.')};try{r.start()}catch{status('Could not start the microphone. Please type your answer below.')}}
function finish(){stopAudio();ended=true;clearInterval(tick);voiceUI();$('#end').disabled=true;$('#mic').disabled=true;$('#health-options').disabled=true;$('#confirm-survey').disabled=true;$('#reply').hidden=true;$('#quiz').hidden=true;$('#subtitle').hidden=true;$('#summary').hidden=false;$('#summary').innerHTML=`<div>${icon('check')}<h2>Thank you for your time!</h2><p>Your session has ended. You can still review the chat history on the left.</p><button class="primary" id="again">Start a new session</button><button class="secondary" id="change">Choose another advisor</button></div>`;$('#again').onclick=startSession;$('#change').onclick=selectPage;status('Session ended. Choose an activity to start again.')}
window.addEventListener('pagehide',()=>{stopAudio();clearInterval(tick)});selectPage();
